// Central configuration for this run - change values here only.
const now = $now.setZone('Africa/Casablanca');
const monday = now.startOf('week');

return [{
  json: {
    newsletter_week: monday.toISODate(),                                   // e.g. 2026-09-21
    newsletter_id: `nl_${now.weekYear}_w${String(now.weekNumber).padStart(2, '0')}`, // e.g. nl_2026_w39
    lookback_days: 7,        // only consider articles collected in the last N days
    max_articles: 40,        // safety cap on LLM calls per run
    min_relevance: 7,        // minimum score (0-10) to be selected
    top_n: 8,                // number of articles in the newsletter
    llm_wait_seconds: 15,    // pause between LLM calls (Groq rate limits)
    summary_language: 'English',
  },
}];

// Instead of DROPPING articles, we TAG them with a rejection reason.
// Rejected articles are saved too, so they are never re-processed next run.
function normalizeTitle(title) {
  return (title || "")
    .toLowerCase()
    .replace(/[^\w\s]/g, "")
    .split(/\s+/)
    .filter(w => w.length > 3);
}

function similarity(a, b) {
  const setA = new Set(a), setB = new Set(b);
  const union = new Set([...setA, ...setB]);
  if (union.size === 0) return 0;
  const inter = [...setA].filter(w => setB.has(w));
  return inter.length / union.size; // Jaccard 0..1
}

const SIMILARITY_THRESHOLD = 0.5;
const kept = [];

return $input.all().map(item => {
  const j = item.json;
  let rejection_reason = "";

  if (!j.is_ai_related) {
    rejection_reason = "rejected_not_ai";
  } else {
    const words = normalizeTitle(j.title);
    const isDuplicate = kept.some(k => similarity(words, k) >= SIMILARITY_THRESHOLD);
    if (isDuplicate) rejection_reason = "rejected_duplicate";
    else kept.push(words);
  }

  return { json: { ...j, rejection_reason } };
});

