// Merge the original article with the LLM result.
// If the LLM failed, llm_ok = false -> the article is NOT saved,
// so it will be retried automatically on the next run.
const a = $('Loop Over Articles').item.json;
const o = $json.output || {};

const CATEGORIES = ["Research", "Product Launch", "Funding & Business",
                    "Policy & Regulation", "Tools & Applications", "Other"];

let score = Number(o.relevance_score);
const llm_ok = typeof o.summary === "string" && o.summary.trim() !== "" && Number.isFinite(score);
if (Number.isFinite(score)) score = Math.min(10, Math.max(0, score));

return {
  json: {
    article_id: a.article_id,
    title: a.title,
    source: a.source,
    url: a.url,
    published_date: a.published_date || "",
    category: CATEGORIES.includes(o.category) ? o.category : "Other",
    summary: (o.summary || "").trim(),
    relevance_score: llm_ok ? score : null,
    llm_ok,
  },
};

// Contract expected by Agent 3 (Newsletter Generation & Delivery).
const cfg = $('Run Config').first().json;

const selected = $input.all()
  .map(i => i.json)
  .filter(r => r.article_id && r.status === 'selected')
  .sort((a, b) => Number(b.relevance_score) - Number(a.relevance_score));

return [{
  json: {
    newsletter_id: cfg.newsletter_id,
    week: cfg.newsletter_week,
    introduction: "",              
    article_count: selected.length,
    articles: selected.map(r => ({
      article_id: r.article_id,
      title: r.title,
      source: r.source,
      original_url: r.url,
      category: r.category,
      summary: r.summary,
      relevance_score: Number(r.relevance_score),
      publication_date: r.published_date || "",
    })),
  },
}];

const keywords = [
  "ai", "artificial intelligence", "machine learning", "ml",
  "llm", "large language model", "gpt", "chatgpt", "openai",
  "deep learning", "neural network", "generative ai", "genai",
  "anthropic", "claude", "gemini", "copilot", "transformer model"
];

const text = `${$json.title || ""} ${$json.raw_content || ""}`.toLowerCase();
const escape = s => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

// Whole-word match: "ai" must not match "said", "email", "again"...
const isAIRelated = keywords.some(k => new RegExp(`\\b${escape(k)}\\b`).test(text));

return { json: { ...$json, is_ai_related: isAIRelated } };
